WALL="$RH/wallpaper.png"
render_svg() { # in out w h
  if command -v rsvg-convert >/dev/null; then rsvg-convert -w "$3" -h "$4" -o "$2" "$1"
  elif /usr/bin/python3 -c 'import gi; gi.require_version("Rsvg","2.0")' 2>/dev/null; then
    /usr/bin/python3 -I - "$@" <<'PY'
import sys, gi
gi.require_version('Rsvg', '2.0'); from gi.repository import Rsvg; import cairo
s, o, w, h = sys.argv[1], sys.argv[2], int(sys.argv[3]), int(sys.argv[4])
hd = Rsvg.Handle.new_from_file(s); sf = cairo.ImageSurface(cairo.FORMAT_ARGB32, w, h)
r = Rsvg.Rectangle(); r.x = r.y = 0; r.width = w; r.height = h
hd.render_document(cairo.Context(sf), r); sf.write_to_png(o)
PY
  elif command -v magick >/dev/null; then magick -background none -density 192 "$1" -resize "${3}x${4}!" "$2"
  else return 1; fi
}
render_svg "$RH/wallpaper.svg" "$WALL" 3840 2160 || { warn "no SVG renderer; using SVG directly"; WALL="$RH/wallpaper.svg"; }

